      out.write("<script>\n");
      out.write("const IS_LOGGED_IN  = ");
      out.print( loginUser != null ? "true" : "false" );
      out.write(";\n");
      out.write("const LOGIN_URL     = '");
      out.print( ctx );
      out.write("/member/login.jsp?redirectURL=");
      out.print( redirectUrl );
      out.write("';\n");
      out.write("const UNIT_PRICE    = ");
      out.print( hat.getHatPrice() );
      out.write(";\n");
      out.write("const MAX_STOCK     = ");
      out.print( Math.max(stock, 1) );
      out.write(";\n");
      out.write("\n");
      out.write("/* ── 수량 변경 ── */\n");
      out.write("function changeQty(delta) {\n");
      out.write("    const input = document.getElementById('qtyDisplay');\n");
      out.write("    let val = parseInt(input.value || 1) + delta;\n");
      out.write("    val = Math.max(1, Math.min(val, MAX_STOCK));\n");
      out.write("    input.value = val;\n");
      out.write("    onQtyChange(val);\n");
      out.write("}\n");
      out.write("\n");
      out.write("function syncQty(input) {\n");
      out.write("    let val = parseInt(input.value);\n");
      out.write("    if (isNaN(val) || val < 1) val = 1;\n");
      out.write("    if (val > MAX_STOCK) val = MAX_STOCK;\n");
      out.write("    input.value = val;\n");
      out.write("    onQtyChange(val);\n");
      out.write("}\n");
      out.write("\n");
      out.write("function onQtyChange(val) {\n");
      out.write("    /* 총 금액 미리보기 갱신 */\n");
      out.write("    const preview = document.getElementById('totalPreview');\n");
      out.write("    if (preview) {\n");
      out.write("        preview.textContent = (UNIT_PRICE * val).toLocaleString('ko-KR') + '원';\n");
      out.write("    }\n");
      out.write("    /* +/- 버튼 상태 */\n");
      out.write("    document.getElementById('btnMinus').disabled = (val <= 1);\n");
      out.write("    document.getElementById('btnPlus').disabled  = (val >= MAX_STOCK);\n");
      out.write("}\n");
      out.write("\n");
      out.write("/* ── 장바구니 제출 ── */\n");
      out.write("function submitCart(buyNow) {\n");
      out.write("    if (!IS_LOGGED_IN) {\n");
      out.write("        location.href = LOGIN_URL;\n");
      out.write("        return;\n");
      out.write("    }\n");
      out.write("    var qty   = parseInt(document.getElementById('qtyDisplay').value) || 1;\n");
      out.write("    var hatNo = document.getElementById('cartHatNo').dataset.no;\n");
      out.write("    var params = 'hatNo=' + hatNo + '&qty=' + qty + '&buyNow=' + (buyNow ? 'Y' : 'N');\n");
      out.write("\n");
      out.write("    fetch('");
      out.print( ctx );
      out.write("/cart/add', {\n");
      out.write("        method: 'POST',\n");
      out.write("        headers: {'Content-Type': 'application/x-www-form-urlencoded'},\n");
      out.write("        body: params\n");
      out.write("    })\n");
      out.write("    .then(function(r) { return r.json(); })\n");
      out.write("    .then(function(data) {\n");
      out.write("        if (data.result === 'ok') {\n");
      out.write("            if (data.redirect) {\n");
      out.write("                location.href = data.redirect;\n");
      out.write("            } else {\n");
      out.write("                if (typeof incrementCartBadge === 'function') incrementCartBadge();\n");
      out.write("                alert(data.msg || '장바구니에 담겼습니다.');\n");
      out.write("            }\n");
      out.write("        } else {\n");
      out.write("            alert(data.msg || '오류가 발생했습니다.');\n");
      out.write("        }\n");
      out.write("    })\n");
      out.write("    .catch(function() { alert('오류가 발생했습니다.'); });\n");
      out.write("}\n");
      out.write("\n");
      out.write("/* ── 초기화 ── */\n");
      out.write("onQtyChange(1);\n");
      out.write("</script>\n");
      out.write("\n");
